//! 🖼️ TIFF directory, tag and twelve independently typed value relationships.
use super::{TiffSnapshot,TiffIfd,TiffTag,TiffValues,TiffByteOrder,TiffFieldType};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{*,artifact::{Cell,Projection,FloatColumn,insert_ieee754,read_binary32,read_binary64,validate_ieee754_row,reconstruct_text,reconstruct_blob}}};
use std::collections::{BTreeMap,BTreeSet};

const FLOAT:&[FloatColumn]=&[FloatColumn::Binary32(3)];
const DOUBLE:&[FloatColumn]=&[FloatColumn::Binary64(3)];
const VALUE_TABLES:[(&str,u16,usize);12]=[("tiff_byte_value",1,4),("tiff_ascii_value",2,2),("tiff_short_value",3,4),("tiff_long_value",4,4),("tiff_rational_value",5,5),("tiff_signed_byte_value",6,4),("tiff_undefined_value",7,4),("tiff_signed_short_value",8,4),("tiff_signed_long_value",9,4),("tiff_signed_rational_value",10,5),("tiff_float_value",11,6),("tiff_double_value",12,6)];
fn integer(value:usize)->Result<i64,String>{i64::try_from(value).map_err(|e|e.to_string())}
fn identity(row:&SqliteRow,columns:usize)->Result<(),String>{if row.rowid<=0||row.values.len()!=columns||row.integer(0)?!=row.rowid{Err("TIFF entity identity or column shape is invalid".into())}else{Ok(())}}
fn tick(control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<(),String>{*count=count.checked_add(1).ok_or("TIFF traversal count overflow")?;if *count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,*count,0)?;}Ok(())}
fn value_count(value:&TiffValues)->usize{match value{TiffValues::Byte(v)|TiffValues::Undefined(v)=>v.len(),TiffValues::Ascii(_)=>1,TiffValues::Short(v)=>v.len(),TiffValues::Long(v)=>v.len(),TiffValues::Rational(v)=>v.len(),TiffValues::SByte(v)=>v.len(),TiffValues::SShort(v)=>v.len(),TiffValues::SLong(v)=>v.len(),TiffValues::SRational(v)=>v.len(),TiffValues::Float(v)=>v.len(),TiffValues::Double(v)=>v.len()}}
fn native_value_size(value:&TiffValues)->Result<usize,String>{let(count,size)=match value{TiffValues::Byte(v)|TiffValues::Undefined(v)=>(v.len(),1),TiffValues::Ascii(v)=>(v.len().checked_add(1).ok_or("TIFF native ASCII count overflow")?,1),TiffValues::Short(v)=>(v.len(),2),TiffValues::Long(v)=>(v.len(),4),TiffValues::Rational(v)=>(v.len(),8),TiffValues::SByte(v)=>(v.len(),1),TiffValues::SShort(v)=>(v.len(),2),TiffValues::SLong(v)=>(v.len(),4),TiffValues::SRational(v)=>(v.len(),8),TiffValues::Float(v)=>(v.len(),4),TiffValues::Double(v)=>(v.len(),8)};u32::try_from(count).map_err(|e|e.to_string())?;count.checked_mul(size).ok_or_else(||"TIFF native value byte count overflow".into())}
fn integers(p:&mut Projection<'_,'_>,table:&str,tag:i64,values:impl Iterator<Item=i64>)->Result<(),String>{for(ordinal,value)in values.enumerate(){p.insert(table,&[Cell::Integer(tag),Cell::Integer(integer(ordinal)?),Cell::Integer(value)])?;}Ok(())}
fn rationals(p:&mut Projection<'_,'_>,table:&str,tag:i64,values:impl Iterator<Item=(i64,i64)>)->Result<(),String>{for(ordinal,(numerator,denominator))in values.enumerate(){p.insert(table,&[Cell::Integer(tag),Cell::Integer(integer(ordinal)?),Cell::Integer(numerator),Cell::Integer(denominator)])?;}Ok(())}
fn ordered<'a>(rows:BTreeMap<usize,&'a SqliteRow>,control:&mut SqliteSnapshotControl<'_>,count:&mut usize)->Result<Vec<&'a SqliteRow>,String>{for(expected,actual)in rows.keys().enumerate(){if expected!=*actual{return Err("TIFF relationship ordinals must be contiguous and zero-based".into());}tick(control,count)?;}control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,*count,0)?;Ok(rows.into_values().collect())}

impl ArtifactSqliteSnapshot for TiffSnapshot{
    fn preflight_sqlite_snapshot_encoding(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{
        use super::{TAG_IMAGE_WIDTH,TAG_IMAGE_LENGTH,TAG_BITS_PER_SAMPLE,TAG_COMPRESSION,TAG_PHOTOMETRIC,TAG_STRIP_OFFSETS,TAG_SAMPLES_PER_PIXEL,TAG_ROWS_PER_STRIP,TAG_STRIP_BYTE_COUNTS};
        let mut bound=artifact::NativeEncodingBound::new(control)?;bound.add(1024)?;bound.check_rows(self.ifds.len())?;let multiplier=if encoding==SnapshotEncoding::Text{8}else{6};let(mut width,mut height)=(None,None);let mut wire=8usize;
        for(index,ifd)in self.ifds.iter().enumerate(){bound.check_rows(ifd.entries.len())?;bound.add(256)?;bound.repeated(ifd.pixels.len(),multiplier)?;let(mut retained,mut rows,mut length)=(0usize,0usize,None);for(tag_index,tag)in ifd.entries.iter().enumerate(){if tag.kind!=tag.values.kind(){return Err("TIFF native field type differs from its value domain".into());}bound.check_rows(value_count(&tag.values))?;let size=native_value_size(&tag.values)?;bound.add(128)?;bound.repeated(size,multiplier)?;wire=wire.checked_add(size).and_then(|n|n.checked_add(32)).ok_or("TIFF native layout overflow")?;if index==0{if tag.tag==TAG_IMAGE_WIDTH&&width.is_none(){width=Some(tag.values.first_u32());}if tag.tag==TAG_IMAGE_LENGTH&&height.is_none(){height=Some(tag.values.first_u32());}if !matches!(tag.tag,TAG_IMAGE_WIDTH|TAG_IMAGE_LENGTH|TAG_BITS_PER_SAMPLE|TAG_COMPRESSION|TAG_PHOTOMETRIC|TAG_STRIP_OFFSETS|TAG_SAMPLES_PER_PIXEL|TAG_ROWS_PER_STRIP|TAG_STRIP_BYTE_COUNTS){retained+=1;}}else{if !matches!(tag.tag,TAG_STRIP_OFFSETS|TAG_STRIP_BYTE_COUNTS){retained+=1;}if tag.tag==TAG_ROWS_PER_STRIP{rows+=1;}if tag.tag==TAG_IMAGE_LENGTH&&length.is_none(){length=Some(tag.values.first_u32());}}if tag_index%256==0{bound.checkpoint()?;}}
            let emitted=if index==0{retained.checked_add(9)}else if !ifd.pixels.is_empty(){if length.flatten().is_some(){retained.checked_sub(rows).and_then(|n|n.checked_add(3))}else{retained.checked_add(2)}}else{Some(retained)}.ok_or("TIFF native directory count overflow")?;u16::try_from(emitted).map_err(|e|e.to_string())?;wire=wire.checked_add(ifd.pixels.len()).and_then(|n|n.checked_add(128)).ok_or("TIFF native layout overflow")?;if index%256==0{bound.checkpoint()?;}}
        let(width,height)=(width.flatten().ok_or("TIFF native encoding requires image width")?,height.flatten().ok_or("TIFF native encoding requires image height")?);if width==0||height==0{return Err("TIFF native encoding requires a nonempty image".into());}let pixels=usize::try_from(width).map_err(|e|e.to_string())?.checked_mul(usize::try_from(height).map_err(|e|e.to_string())?).and_then(|n|n.checked_mul(4)).ok_or("TIFF native raster dimensions overflow")?;if pixels!=self.pixels.len(){return Err("TIFF native RGBA pixel count differs from image dimensions".into());}bound.repeated(pixels,multiplier)?;wire=wire.checked_add(pixels).ok_or("TIFF native layout overflow")?;u32::try_from(wire).map_err(|e|e.to_string())?;bound.finish()
    }
    const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
    fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
        control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;let mut rows=2usize;let mut counted=0usize;control.check_rows(rows)?;
        for(count,ifd)in self.ifds.iter().enumerate(){rows=rows.checked_add(2).ok_or("TIFF row count overflow")?;control.check_rows(rows.checked_add(1).ok_or("TIFF metadata row overflow")?)?;for tag in &ifd.entries{rows=rows.checked_add(1).and_then(|n|n.checked_add(value_count(&tag.values))).ok_or("TIFF row count overflow")?;control.check_rows(rows.checked_add(1).ok_or("TIFF metadata row overflow")?)?;counted=counted.checked_add(1).ok_or("TIFF traversal count overflow")?;if counted%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,counted,0)?;}}if count%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,self.ifds.len())?;}}
        let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;
        p.insert_key("tiff_document",1,&[Cell::Text(&self.schema),Cell::Text(match self.byte_order{TiffByteOrder::LittleEndian=>"littleEndian",TiffByteOrder::BigEndian=>"bigEndian"})])?;
        p.insert_key("tiff_document_pixels",1,&[Cell::Blob(&self.pixels)])?;
        for(ordinal,ifd)in self.ifds.iter().enumerate(){let ifd_id=p.insert("tiff_ifd",&[Cell::Integer(1),Cell::Integer(integer(ordinal)?)])?;p.insert_key("tiff_ifd_pixels",ifd_id,&[Cell::Blob(&ifd.pixels)])?;
            for(ordinal,tag)in ifd.entries.iter().enumerate(){let tag_id=p.insert("tiff_tag",&[Cell::Integer(ifd_id),Cell::Integer(integer(ordinal)?),Cell::Integer(i64::from(tag.tag)),Cell::Integer(i64::from(tag.kind.to_u16())),Cell::Integer(i64::from(tag.values.kind().to_u16()))])?;
                match &tag.values{
                    TiffValues::Byte(v)=>integers(&mut p,"tiff_byte_value",tag_id,v.iter().copied().map(i64::from))?,
                    TiffValues::Ascii(v)=>p.insert_key("tiff_ascii_value",tag_id,&[Cell::Text(v)])?,
                    TiffValues::Short(v)=>integers(&mut p,"tiff_short_value",tag_id,v.iter().copied().map(i64::from))?,
                    TiffValues::Long(v)=>integers(&mut p,"tiff_long_value",tag_id,v.iter().copied().map(i64::from))?,
                    TiffValues::Rational(v)=>rationals(&mut p,"tiff_rational_value",tag_id,v.iter().map(|&(n,d)|(i64::from(n),i64::from(d))))?,
                    TiffValues::SByte(v)=>integers(&mut p,"tiff_signed_byte_value",tag_id,v.iter().copied().map(i64::from))?,
                    TiffValues::Undefined(v)=>integers(&mut p,"tiff_undefined_value",tag_id,v.iter().copied().map(i64::from))?,
                    TiffValues::SShort(v)=>integers(&mut p,"tiff_signed_short_value",tag_id,v.iter().copied().map(i64::from))?,
                    TiffValues::SLong(v)=>integers(&mut p,"tiff_signed_long_value",tag_id,v.iter().copied().map(i64::from))?,
                    TiffValues::SRational(v)=>rationals(&mut p,"tiff_signed_rational_value",tag_id,v.iter().map(|&(n,d)|(i64::from(n),i64::from(d))))?,
                    TiffValues::Float(v)=>for(ordinal,&value)in v.iter().enumerate(){insert_ieee754(&mut p,"tiff_float_value",&[Cell::Integer(tag_id),Cell::Integer(integer(ordinal)?),Cell::Float32(value)],FLOAT)?;},
                    TiffValues::Double(v)=>for(ordinal,&value)in v.iter().enumerate(){insert_ieee754(&mut p,"tiff_double_value",&[Cell::Integer(tag_id),Cell::Integer(integer(ordinal)?),Cell::Real(value)],DOUBLE)?;},
                }
            }
        }p.finish()
    }
    fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
        control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|e|e.to_string())?;
        let document=database.table("tiff_document")?.single_row()?;identity(document,3)?;if document.rowid!=1{return Err("TIFF document requires identifier1".into());}let byte_order=match document.text(2)?{"littleEndian"=>TiffByteOrder::LittleEndian,"bigEndian"=>TiffByteOrder::BigEndian,_=>return Err("unknown TIFF byte order".into())};
        let mut checked=0usize;let mut ifd_ids=BTreeSet::new();let directories=artifact::ordered_row_refs(database.table("tiff_ifd")?,2,control)?;for row in &directories{identity(row,3)?;if row.integer(1)?!=1||!ifd_ids.insert(row.rowid){return Err("invalid TIFF directory ownership".into());}tick(control,&mut checked)?;}
        let mut tags=BTreeMap::new();let mut directory_tags=BTreeMap::<i64,BTreeMap<usize,&SqliteRow>>::new();
        for row in &database.table("tiff_tag")?.rows{identity(row,6)?;if !ifd_ids.contains(&row.integer(1)?)||tags.insert(row.rowid,row).is_some(){return Err("TIFF tag directory is dangling or identity is duplicated".into());}u16::try_from(row.integer(3)?).map_err(|e|e.to_string())?;TiffFieldType::from_u16(u16::try_from(row.integer(4)?).map_err(|e|e.to_string())?)?;TiffFieldType::from_u16(u16::try_from(row.integer(5)?).map_err(|e|e.to_string())?)?;let ordinal=usize::try_from(row.integer(2)?).map_err(|e|e.to_string())?;if directory_tags.entry(row.integer(1)?).or_default().insert(ordinal,row).is_some(){return Err("duplicate TIFF tag ordinal".into());}tick(control,&mut checked)?;}
        let mut values=BTreeMap::<i64,BTreeMap<usize,&SqliteRow>>::new();let mut ascii=BTreeMap::new();
        for(table,kind,columns)in VALUE_TABLES{let mut identities=BTreeSet::new();for row in &database.table(table)?.rows{identity(row,columns)?;if !identities.insert(row.rowid){return Err("duplicate TIFF typed value identity".into());}let owner=if kind==2{row.rowid}else{row.integer(1)?};if tags.get(&owner).ok_or("dangling TIFF value tag")?.integer(5)?!=i64::from(kind){return Err("TIFF value component differs from its declared variant".into());}if kind==2{row.text(1)?;if ascii.insert(owner,row).is_some(){return Err("duplicate TIFF ASCII component".into());}}else{let ordinal=usize::try_from(row.integer(2)?).map_err(|e|e.to_string())?;if values.entry(owner).or_default().insert(ordinal,row).is_some(){return Err("duplicate TIFF typed value ordinal".into());}if kind==11{validate_ieee754_row(row,4,FLOAT)?;read_binary32(row,3,FLOAT)?;}else if kind==12{validate_ieee754_row(row,4,DOUBLE)?;read_binary64(row,3,DOUBLE)?;}else{row.integer(3)?;if kind==5||kind==10{row.integer(4)?;}}}tick(control,&mut checked)?;}}
        let root_pixels=database.table("tiff_document_pixels")?.single_row()?;identity(root_pixels,2)?;if root_pixels.rowid!=1{return Err("TIFF document pixels require document1".into());}let pixels=reconstruct_blob(control,root_pixels.blob(1)?)?;
        let directory_pixels=database.table("tiff_ifd_pixels")?;if directory_pixels.rows.len()!=ifd_ids.len(){return Err("TIFF directories require one pixel component each".into());}let mut pixel_components=BTreeMap::new();for row in &directory_pixels.rows{identity(row,2)?;row.blob(1)?;if !ifd_ids.contains(&row.rowid)||pixel_components.insert(row.rowid,row).is_some(){return Err("dangling or duplicate TIFF directory pixels".into());}tick(control,&mut checked)?;}
        let mut ifds=Vec::new();for directory in directories{let pixels=reconstruct_blob(control,pixel_components.remove(&directory.rowid).ok_or("missing TIFF directory pixels")?.blob(1)?)?;let ordered_tags=ordered(directory_tags.remove(&directory.rowid).unwrap_or_default(),control,&mut checked)?;let mut entries=Vec::new();for tag in ordered_tags{
            let rows=ordered(values.remove(&tag.rowid).unwrap_or_default(),control,&mut checked)?;let variant=tag.integer(5)?;
            let values=match variant{
                1=>TiffValues::Byte(rows.iter().map(|r|{tick(control,&mut checked)?;u8::try_from(r.integer(3)?).map_err(|e|e.to_string())}).collect::<Result<_,_>>()?),
                2=>TiffValues::Ascii(reconstruct_text(control,ascii.remove(&tag.rowid).ok_or("missing TIFF ASCII component")?.text(1)?)?),
                3=>TiffValues::Short(rows.iter().map(|r|{tick(control,&mut checked)?;u16::try_from(r.integer(3)?).map_err(|e|e.to_string())}).collect::<Result<_,_>>()?),
                4=>TiffValues::Long(rows.iter().map(|r|{tick(control,&mut checked)?;u32::try_from(r.integer(3)?).map_err(|e|e.to_string())}).collect::<Result<_,_>>()?),
                5=>TiffValues::Rational(rows.iter().map(|r|{tick(control,&mut checked)?;Ok((u32::try_from(r.integer(3)?).map_err(|e|e.to_string())?,u32::try_from(r.integer(4)?).map_err(|e|e.to_string())?))}).collect::<Result<_,String>>()?),
                6=>TiffValues::SByte(rows.iter().map(|r|{tick(control,&mut checked)?;i8::try_from(r.integer(3)?).map_err(|e|e.to_string())}).collect::<Result<_,_>>()?),
                7=>TiffValues::Undefined(rows.iter().map(|r|{tick(control,&mut checked)?;u8::try_from(r.integer(3)?).map_err(|e|e.to_string())}).collect::<Result<_,_>>()?),
                8=>TiffValues::SShort(rows.iter().map(|r|{tick(control,&mut checked)?;i16::try_from(r.integer(3)?).map_err(|e|e.to_string())}).collect::<Result<_,_>>()?),
                9=>TiffValues::SLong(rows.iter().map(|r|{tick(control,&mut checked)?;i32::try_from(r.integer(3)?).map_err(|e|e.to_string())}).collect::<Result<_,_>>()?),
                10=>TiffValues::SRational(rows.iter().map(|r|{tick(control,&mut checked)?;Ok((i32::try_from(r.integer(3)?).map_err(|e|e.to_string())?,i32::try_from(r.integer(4)?).map_err(|e|e.to_string())?))}).collect::<Result<_,String>>()?),
                11=>TiffValues::Float(rows.iter().map(|r|{tick(control,&mut checked)?;read_binary32(r,3,FLOAT)}).collect::<Result<_,_>>()?),
                12=>TiffValues::Double(rows.iter().map(|r|{tick(control,&mut checked)?;read_binary64(r,3,DOUBLE)}).collect::<Result<_,_>>()?),
                _=>return Err("unknown TIFF value variant".into()),
            };entries.push(TiffTag{tag:u16::try_from(tag.integer(3)?).map_err(|e|e.to_string())?,kind:TiffFieldType::from_u16(u16::try_from(tag.integer(4)?).map_err(|e|e.to_string())?)?,values});tick(control,&mut checked)?;
        }ifds.push(TiffIfd{entries,pixels});tick(control,&mut checked)?;}
        if !values.is_empty()||!ascii.is_empty()||!directory_tags.is_empty(){return Err("unowned TIFF relational components".into());}control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,checked,checked)?;Ok(Self{schema:reconstruct_text(control,document.text(1)?)?,byte_order,ifds,pixels})
    }
    fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_os_kernel::io_schema::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
        control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;if dialect.artifact_kind!="s.stdio.tiff"||dialect.standard!="6.0"{return Err(String::from("owned TIFF dialect differs from its semantic standard").into());}let row=database.table("tiff_document")?.single_row()?;if row.rowid!=1||row.text(1)?!=self.schema{return Err(String::from("owned TIFF document identity differs from semantic projection").into());}let diagnostics=match dialect.subset.as_str(){"*"=>Vec::new(),"baseline"=>crate::standards::v6_0::subsets::baseline::schema::check_tiff_baseline_conformance_controlled(self,control)?,_=>return Err(String::from("unknown owned TIFF subset").into())};Ok(semio_framework_os_kernel::io_schema::IoOutcome{value:(),diagnostics})
    }
}
